// ===== Amazon Toolkit core: market stats v2 =====
// Shared by i1, i2, i3 and i4. Input: cleaned listings for ONE keyword (output of cleanListings).
// Changes vs v1:
//  - Variations of one product (same brand + same shared review count + same rating) are grouped into a "family".
//    Amazon shares reviews across color / pattern / pack-size variations, and page 1 lists each one separately,
//    so v1 counted the same reviews several times.
//  - Review stats are per family. Sales stats are per family (children's sales badges are summed).
//  - "new entrants" -> "low-review sellers": families under 1,000 reviews selling 1K+/month. No launch dates exist,
//    so "new" was not something the data could show.
//  - Concentration and brand dominance are measured on SALES (units), not on listing counts or review counts.
//  - Opportunity score 0-100 from five continuous parts, with the breakdown. No enter/avoid verdict.

const CORE_VERSION = 'core v2.6 (2026-10-18)';
// Price and demand thresholds are in US dollars. Other marketplaces are converted before they are judged.
// Fixed rates (exchange-rates.org, 2 Oct 2026), so the same page always gets the same score. Update them a few times a year.
const USD_PER = { 'amazon.com': 1, 'amazon.co.uk': 1.32, 'amazon.ca': 0.70 };

function quantile(arr, q) {
  if (arr.length === 0) return null;
  const s = [...arr].sort((a, b) => a - b);
  const pos = (s.length - 1) * q;
  const lo = Math.floor(pos), hi = Math.ceil(pos);
  return s[lo] + (s[hi] - s[lo]) * (pos - lo);
}
const r = (n, d = 2) => (n === null || n === undefined || Number.isNaN(n) ? null : Math.round(n * 10 ** d) / 10 ** d);
const clamp01 = x => Math.max(0, Math.min(1, x));
const stem = w => (w.length > 3 ? w.replace(/(es|s)$/, '') : w);
const kwStemsOf = keyword => (keyword || '').toLowerCase().split(/\s+/)
  .map(w => w.replace(/[^a-z0-9]/g, '')).filter(Boolean).map(stem);

// The first title word is often not a brand ("Resistance Bands ...", "Exercise Bands ...")
const GENERIC = new Set(['exercise', 'workout', 'fitness', 'pull', 'long', 'fabric', 'heavy', 'pedal',
  'set', 'pack', 'premium', 'professional', 'upgraded', 'new', 'the', 'for', 'with', 'women', 'womens',
  'men', 'mens', 'kids', 'adjustable', 'home', 'portable', 'large', 'small', 'extra']);
function cleanBrand(b, kwStems, pageGeneric) {
  if (!b) return null;
  const w = b.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (w.length < 2 || GENERIC.has(w) || kwStems.includes(stem(w)) || (pageGeneric && pageGeneric.has(w))) return null;
  return b;
}
// Words that start some titles but are really descriptions ("Kitchen Mat…", "Ergonomic Mouse Pad…").
// A real brand starts titles; a generic word mostly appears INSIDE other titles. Rule, set on Oct 17 batch data:
// generic when it appears inside at least 5 titles that don't start with it, and at least twice as often inside as at the start.
// Caught: Kitchen, Ergonomic, Gaming, Office, Boys, Garden, Insulated... Kept: Purina, Dawn, Lodge, Friskies, OxiClean, Joseph Joseph.
function genericWordsOnPage(all) {
  const titles = all.map(i => String(i.title || '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(Boolean));
  const out = new Set();
  const firsts = new Set(titles.map(t => t[0]).filter(Boolean));
  for (const w of firsts) {
    const first = titles.filter(t => t[0] === w).length;
    const inside = titles.filter(t => t[0] !== w && t.slice(1).includes(w)).length;
    if (inside >= 5 && inside >= 2 * first) out.add(w);
  }
  return out;
}
const brandKey = b => (b ? b.toLowerCase().replace(/[^a-z0-9]/g, '') : null);

// ---------- Variation families ----------
// Two listings are one family when: shared review count >= 50, same rating, and
//  - same brand (when the brand is known), or
//  - brand unknown on both and titles overlap >= 50% of words.
// Under 50 reviews, equal counts happen by chance too often, so each listing stays on its own.
const titleWords = t => new Set((t || '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(w => w.length >= 3));
function jaccard(a, b) {
  let inter = 0;
  for (const x of a) if (b.has(x)) inter++;
  const uni = a.size + b.size - inter;
  return uni ? inter / uni : 0;
}
function groupFamilies(items, kwStems, pageGeneric) {
  const families = [];
  for (const i of items) {
    const brand = cleanBrand(i.brand_guess, kwStems, pageGeneric);
    const bk = brandKey(brand);
    const words = titleWords(i.title);
    let fam = null;
    if ((i.reviews ?? 0) >= 50 && i.rating !== null && i.rating !== undefined) {
      fam = families.find(f => f.reviews === i.reviews && f.rating === i.rating && (
        bk ? f.brand_key === bk : (!f.brand_key && jaccard(f.words, words) >= 0.5)));
    }
    if (fam) {
      fam.children.push(i);
      for (const w of words) fam.words.add(w);
    } else {
      families.push({ family_id: i.asin, brand, brand_key: bk, reviews: i.reviews ?? 0, rating: i.rating ?? null, words: new Set(words), children: [i] });
    }
  }
  for (const f of families) {
    f.units = f.children.reduce((s, c) => s + (c.bought_last_month ?? 0), 0);
    f.has_sales = f.children.some(c => c.bought_last_month !== null && c.bought_last_month !== undefined);
    f.price_median = quantile(f.children.map(c => c.price), 0.5);
    f.title = f.children[0].title;
    delete f.words;
  }
  return families;
}

// ---------- Market stats for one keyword ----------
function marketStats(all, _check = true) {
  const keyword = all[0]?.keyword ?? null;
  const marketplace = all[0]?.marketplace ?? 'amazon.com';
  const kwStems = kwStemsOf(keyword);
  const DEAL = /prime big deal|prime day|lightning deal|deal of the day/i;
  const fx = USD_PER[marketplace] ?? 1;
  const inUsd = v => { if (fx === 1) return ''; const u = v * fx; return ` (about $${u >= 1e6 ? (u / 1e6).toFixed(2) + 'M' : u >= 1e4 ? Math.round(u / 1e3) + 'K' : Math.round(u)})`; };

  // 1. Relevance, bulk packs, price outliers: unchanged from v1 (tested Oct 7-9)
  const packQty = t => {
    const m = (t || '').match(/(\d+)\s*[- ]?\s*(pack|pcs|pieces|pk|count|ct)\b/i);
    return m ? parseInt(m[1], 10) : 1;
  };
  const isBulk = i => /\bbulk\b/i.test(i.title || '') || packQty(i.title) >= 6;
  const relevantAll = all.filter(i => i.relevant !== false);
  const bulkCandidates = relevantAll.filter(isBulk);
  const singles = relevantAll.filter(i => !isBulk(i));
  const medianPrice = arr => quantile(arr.map(i => i.price), 0.5);
  const bulkIsSeparate = bulkCandidates.length > 0 && singles.length >= 5
    && medianPrice(bulkCandidates) >= 2.5 * medianPrice(singles);
  const bulk = bulkIsSeparate ? bulkCandidates : [];
  const items = bulkIsSeparate ? singles : relevantAll;

  const q1 = quantile(items.map(i => i.price), 0.25);
  const q3 = quantile(items.map(i => i.price), 0.75);
  const iqr = (q3 ?? 0) - (q1 ?? 0);
  const fenceLow = q1 - 1.5 * iqr, fenceHigh = q3 + 1.5 * iqr;
  const isOutlier = i => iqr > 0 && (i.price < fenceLow || i.price > fenceHigh);
  const core = items.filter(i => !isOutlier(i));
  if (core.length < 5) {
    const words = (keyword || '').toLowerCase().split(/\s+/).map(w => w.replace(/[^a-z0-9]/g, '')).filter(Boolean);
    const hits = words.map(w => [w, all.filter(i => (i.title || '').toLowerCase().includes(stem(w))).length]);
    const [worst, n] = hits.sort((a, b) => a[1] - b[1])[0] || ['', 0];
    throw new Error(`Only ${core.length} usable listings for "${keyword}" (${all.length} found, ${bulk.length} bulk packs set aside). "${worst}" appears in ${n} of ${all.length} titles, so try the keyword without it.`);
  }
  const outliers = items.filter(isOutlier);
  const corePrices = core.map(i => i.price);

  const excluded = {};
  for (const i of all) if (i.relevant === false) excluded[`${i.asin}|${i.position}`] = i.match_type === 'none' ? 'product word not in title' : 'accessory';
  for (const i of bulk) excluded[`${i.asin}|${i.position}`] = 'bulk pack (separate market)';
  for (const i of outliers) excluded[`${i.asin}|${i.position}`] = 'price outlier';

  // 2. Families (variations grouped)
  const pageGeneric = genericWordsOnPage(all);
  const families = groupFamilies(core, kwStems, pageGeneric);
  const familyOf = {};
  for (const f of families) for (const c of f.children) familyOf[`${c.asin}|${c.position}`] = f.family_id;
  const multi = families.filter(f => f.children.length > 1);

  // 3. Sales (Amazon shows ranges like "1K+", so every unit figure is a minimum)
  const unitsFloor = families.reduce((s, f) => s + f.units, 0);
  const listingsMissingSales = core.filter(i => i.bought_last_month === null || i.bought_last_month === undefined).length;
  const share = u => (unitsFloor ? u / unitsFloor : 0);

  // 4. Who holds the sales
  const byUnits = [...families].sort((a, b) => b.units - a.units);
  const top3FamilyUnitShare = share(byUnits.slice(0, 3).reduce((s, f) => s + f.units, 0));
  const brandUnits = {};
  const brandName = {};
  let unknownBrandUnits = 0;
  for (const f of families) {
    if (f.brand_key) { brandUnits[f.brand_key] = (brandUnits[f.brand_key] || 0) + f.units; brandName[f.brand_key] ??= f.brand; }
    else unknownBrandUnits += f.units;
  }
  const topBrands = Object.entries(brandUnits).sort((a, b) => b[1] - a[1]).slice(0, 5)
    .map(([k, u]) => ({ brand: brandName[k], units: u, share_pct: r(share(u) * 100, 1), families: families.filter(f => f.brand_key === k).length }));
  const topBrandShare = topBrands[0] ? share(topBrands[0].units) : 0;
  const amazonOwn = families.filter(f => f.brand_key === 'amazon');

  // 5. Review moat, per family (each shared review count once)
  const famReviews = families.map(f => f.reviews);
  const medianFamilyReviews = Math.round(quantile(famReviews, 0.5));
  const totalFamReviews = famReviews.reduce((s, x) => s + x, 0);
  const top3ReviewShare = totalFamReviews
    ? [...famReviews].sort((a, b) => b - a).slice(0, 3).reduce((s, x) => s + x, 0) / totalFamReviews : 0;

  // 6. Low-review sellers: families under 1,000 reviews selling 1K+/month
  // A low-review product from a brand that already has a 1,000+ review product on this page is that brand's
  // new listing (a new size, or a variation that no longer shares reviews since Amazon's 2026 change), not a newcomer.
  // Oct 17: Lodge's own 83-296 review skillets were counted as newcomers and lifted "cast iron skillet".
  const establishedBrands = new Set(families.filter(f => f.brand_key && f.reviews >= 1000).map(f => f.brand_key));
  const isNewcomer = f => f.reviews < 1000 && !(f.brand_key && establishedBrands.has(f.brand_key));
  const lowRev = families.filter(f => isNewcomer(f) && f.units >= 1000);
  const lowRevUnitsAll = families.filter(isNewcomer).reduce((s, f) => s + f.units, 0);
  const lowRevPrices = lowRev.map(f => f.price_median);
  const lowRevRatings = lowRev.map(f => f.rating).filter(x => x !== null && x !== undefined);

  // 7. Sale events
  const dealShare = core.filter(i => DEAL.test(i.badges || '')).length / core.length * 100;
  const notInDeal = core.filter(i => !DEAL.test(i.badges || ''));

  // 8. Opportunity score: five continuous parts, each 0-1. Weights are a judgement call, written out so they can be argued with.
  // v2.1 (after the Oct 16 live test):
  //  - Demand is a MULTIPLIER, not one part of a sum. An easy market nobody buys from is not an opportunity
  //    ("bonsai tools": 93% of sales to low-review products, but only 1,400 units / ~$50K a month on all of page 1, scored 81 in v2.0).
  //  - Demand is measured in revenue, not units, so a $67 paddle and a $9 phone stand are compared fairly.
  //  - Brand openness uses the TOP 3 brands' share. One brand at 31% looked open in v2.0 while Colgate + Crest + Sensodyne held 82%.
  const top3BrandShare = topBrands.slice(0, 3).reduce((s, b) => s + share(b.units), 0);
  const revenueFloor = families.reduce((s, f) => s + f.children.reduce((t, c) => t + (c.bought_last_month ?? 0) * c.price, 0), 0);
  const parts = [
    { key: 'low_review_sales', weight: 35, value: clamp01(share(lowRevUnitsAll) / 0.20),
      why: `${r(share(lowRevUnitsAll) * 100, 1)}% of sales go to newcomers (under 1,000 reviews, from brands with no established product on the page; 20%+ = full marks)` },
    { key: 'brand_openness', weight: 30, value: 1 - clamp01((top3BrandShare - 0.30) / 0.50),
      why: topBrands.length ? `top 3 brands (${topBrands.slice(0, 3).map(b => b.brand).join(', ')}) hold ${r(top3BrandShare * 100, 1)}% of sales (30% or less = full marks, 80%+ = zero)` : 'no brand identified' },
    { key: 'review_moat', weight: 25, value: 1 - clamp01((Math.log10(Math.max(medianFamilyReviews, 1)) - 3) / 1.5),
      why: `median product has ${medianFamilyReviews.toLocaleString('en-US')} reviews (1,000 or less = full marks, 31,600+ = zero)` },
    { key: 'price_room', weight: 10, value: clamp01((quantile(corePrices, 0.5) * fx - 8) / 12),
      why: `median price ${CURRENCY[marketplace] ?? ''}${quantile(corePrices, 0.5).toFixed(2)}${inUsd(quantile(corePrices, 0.5))} ($8 or less = zero, $20+ = full marks)` },
  ];
  const openness = parts.reduce((s, p) => s + p.weight * p.value, 0); // 0-100: how easy it is to get in
  const demandValue = clamp01((Math.log10(Math.max(revenueFloor * fx, 1)) - 4) / 3); // $10K/month = 0, $10M+/month = 1
  const demandFactor = 0.2 + 0.8 * demandValue; // even a dead market keeps 20%, so openness still shows in the ranking
  const score = Math.round(openness * demandFactor);
  const scoreBreakdown = [
    ...parts.map(p => `${p.key} ${r(p.weight * p.value, 1)}/${p.weight}: ${p.why}`),
    `openness ${r(openness, 1)}/100 x demand ${r(demandFactor, 2)}: at least ${Math.round(revenueFloor)} in sales last month on page 1${inUsd(revenueFloor)} ($10K or less = x0.2, $10M+ = x1.0)`,
  ];

  // 9. Confidence: how far to trust this one snapshot (stability vs the previous run is added by the caller)
  let conf = 2;
  const confNotes = [];
  if (dealShare > 30) { conf--; confNotes.push('sale event running, prices are temporary'); }
  if (all.length < 30) { conf--; confNotes.push(`Amazon returned only ${all.length} organic listings on page 1 (usually 40-60), so this is a thin sample`); }
  else if (families.length < 15) { conf--; confNotes.push(`only ${families.length} distinct products after grouping variations`); }
  if (listingsMissingSales > core.length / 2) { conf--; confNotes.push('most listings show no sales data'); }
  const exactShare = core.filter(i => i.match_type !== 'broad').length / core.length * 100;
  const headWord = (keyword || '').trim().split(/\s+/).pop();
  if (exactShare < 50) { conf--; confNotes.push(`only ${Math.round(exactShare)}% of listings contain every keyword word; results describe the broader "${headWord}" market`); }
  // Relevance check (added after the Oct 17 manual check): the title filter keeps only listings whose title or URL
  // contains the product word. Real products named differently ("Dawn Dishwashing Liquid" for "dish soap",
  // "Wazakura Bonsai Scissors" for "bonsai tools") get left out. When those hold 15%+ of page-1 sales, say so and
  // show what the score would be with them counted. Tested on 15 markets: the tier never changed, the score moved 0-5.
  const pageUnits = all.reduce((s, i) => s + (i.bought_last_month ?? 0), 0);
  const notInTitle = all.filter(i => i.match_type === 'none');
  const notInTitleShare = pageUnits ? notInTitle.reduce((s, i) => s + (i.bought_last_month ?? 0), 0) / pageUnits : 0;
  let scoreIfIncluded = null;
  if (_check && notInTitleShare >= 0.15) {
    try { scoreIfIncluded = marketStats(all.map(i => (i.match_type === 'none' ? { ...i, relevant: true, match_type: 'broad' } : i)), false).opportunity_score; } catch (e) { scoreIfIncluded = null; }
    const examples = [...notInTitle].sort((a, b) => (b.bought_last_month ?? 0) - (a.bought_last_month ?? 0)).slice(0, 2).map(i => `"${i.title.slice(0, 45)}"`).join(', ');
    confNotes.push(`${r(notInTitleShare * 100, 0)}% of page-1 sales are listings without "${headWord}" in the title (e.g. ${examples}), left out of the stats; counted in, the score would be ${scoreIfIncluded ?? 'n/a'}. Check them in Listings (excluded_reason = product word not in title)`);
  }
  const unknownShare = share(unknownBrandUnits);
  if (unknownShare > 0.4) { conf--; confNotes.push(`brand unknown for ${r(unknownShare * 100, 0)}% of sales (titles start with generic words), so brand_openness is unverified`); }

  return {
    core_version: CORE_VERSION,
    keyword, marketplace,
    checked_at: all[0]?.checked_at ?? null,
    listings_total: all.length,
    thin_page: all.length < 30,
    listings_irrelevant: all.length - relevantAll.length,
    bulk_listings: bulk.length,
    outliers_removed: outliers.length,
    listings_analyzed: core.length,
    products_analyzed: families.length,
    variation_groups: multi.length,
    exact_match_pct: Math.round(exactShare),
    price_p25: r(quantile(corePrices, 0.25)),
    price_median: r(quantile(corePrices, 0.5)),
    price_p75: r(quantile(corePrices, 0.75)),
    avg_rating: r(families.reduce((s, f) => s + (f.rating ?? 0), 0) / families.filter(f => f.rating !== null).length, 2),
    median_reviews: medianFamilyReviews,
    top3_review_share_pct: r(top3ReviewShare * 100, 1),
    units_last_month_floor: unitsFloor,
    revenue_last_month_floor: Math.round(revenueFloor),
    openness_score: Math.round(openness),
    demand_factor: r(demandFactor, 2),
    top3_brands_sales_share_pct: r(top3BrandShare * 100, 1),
    listings_missing_sales: listingsMissingSales,
    top3_products_sales_share_pct: r(top3FamilyUnitShare * 100, 1),
    top_brand: topBrands[0]?.brand ?? '',
    top_brand_sales_share_pct: r(topBrandShare * 100, 1),
    unknown_brand_sales_share_pct: r(unknownShare * 100, 1),
    amazon_own_brand_products: amazonOwn.length,
    low_review_sellers_count: lowRev.length,
    low_review_sales_share_pct: r(share(lowRevUnitsAll) * 100, 1),
    low_review_price_median: r(quantile(lowRevPrices, 0.5)),
    low_review_avg_rating: lowRevRatings.length ? r(lowRevRatings.reduce((s, x) => s + x, 0) / lowRevRatings.length, 2) : null,
    deal_event_share_pct: r(dealShare, 1),
    discounted_outside_event_pct: notInDeal.length ? r(notInDeal.filter(i => i.discount_pct > 0).length / notInDeal.length * 100, 1) : null,
    small_business_listings: core.filter(i => i.small_business).length,
    opportunity_score: score,
    score_breakdown: scoreBreakdown,
    confidence_points: conf,
    confidence_notes: confNotes,
    top_brands: topBrands,
    low_review_sellers: lowRev.map(f => ({ family_id: f.family_id, brand: f.brand, price: r(f.price_median), rating: f.rating, reviews: f.reviews, units: f.units, title: f.title.slice(0, 80) })),
    outliers: outliers.map(i => ({ asin: i.asin, title: i.title.slice(0, 60), price: i.price })),
    families: families.map(f => {
      const best = [...f.children].sort((a, b) => (b.bought_last_month ?? -1) - (a.bought_last_month ?? -1) || a.position - b.position)[0];
      return { family_id: f.family_id, brand: f.brand, reviews: f.reviews, rating: f.rating, units: f.units, has_sales: f.has_sales,
        asins: f.children.map(c => c.asin), best_asin: best.asin, title: best.title, price: r(f.price_median),
        position: Math.min(...f.children.map(c => c.position ?? 999)) };
    }),
    excluded,
    family_of: familyOf,
  };
}

// ---------- Overlap between two sets of counted listings ----------
// Sales-weighted: "what share of A's sales sit on products B also shows". Jaccard alone over-reacts to the
// low-selling tail, which churns most.
function overlap(A, B) {
  const a = new Map(A.map(i => [i.asin, i])), b = new Map(B.map(i => [i.asin, i]));
  const shared = [...a.keys()].filter(k => b.has(k));
  const units = (m, keys) => keys.reduce((s, k) => s + (m.get(k).bought_last_month ?? 0), 0);
  const ua = units(a, [...a.keys()]), ub = units(b, [...b.keys()]);
  return {
    shared_products: shared.length,
    jaccard: r(shared.length / new Set([...a.keys(), ...b.keys()]).size, 2),
    a_sales_on_shared_pct: ua ? r(units(a, shared) / ua * 100, 1) : null,
    b_sales_on_shared_pct: ub ? r(units(b, shared) / ub * 100, 1) : null,
    min_sales_on_shared_pct: ua && ub ? r(Math.min(units(a, shared) / ua, units(b, shared) / ub) * 100, 1) : null,
  };
}
const counted = (listings, stats) => listings.filter(i => !stats.excluded[`${i.asin}|${i.position}`]);

// ---------- Stability: this run vs the previous run of the same keyword ----------
// Calibrated on 19 saved runs (Oct 9-15): resistance band 97-99% (score moved 1-4 points),
// pet food 81-87% (0-2), hair oil 73-84% (2-8), yoga mat 47-79% (2-12).
function stability(curListings, curStats, prevListings, prevStats) {
  if (!prevListings || !prevListings.length) return { stability: 'no previous run', note: 'first run of this keyword, stability not measured' };
  const fp = ls => ls.map(i => `${i.asin}|${i.price}|${i.reviews}`).sort().join(',');
  if (fp(curListings) === fp(prevListings)) return { stability: 'cached copy', note: 'identical to the previous run (SerpApi serves cached results for 1 hour), so not a new measurement' };
  const o = overlap(counted(curListings, curStats), counted(prevListings, prevStats));
  const m = o.min_sales_on_shared_pct;
  const label = m >= 80 ? 'stable' : m >= 60 ? 'moderate' : 'unstable';
  return {
    stability: label,
    prev_checked_at: prevStats.checked_at,
    sales_on_shared_with_prev_pct: m,
    products_shared_with_prev: o.shared_products,
    score_change: curStats.opportunity_score - prevStats.opportunity_score,
    price_median_change: r(curStats.price_median - prevStats.price_median),
    note: `${m}% of sales sit on products that were also on page 1 at ${prevStats.checked_at}`,
  };
}

// ---------- Variants: group keywords in one batch that are really the same market ----------
// Same market when at least 70% of EACH keyword's sales sit on products both keywords show.
// Measured so far: resistance band vs bands 92-96% (same market); unrelated keywords under 5%.
// 30-70% = overlapping: reported, not merged.
function groupVariants(results) {
  // results: [{ keyword, marketplace, listings, stats }] (status ok only)
  const n = results.length;
  const parent = [...Array(n).keys()];
  const find = x => (parent[x] === x ? x : (parent[x] = find(parent[x])));
  const pairs = [];
  for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) {
    if (results[i].marketplace !== results[j].marketplace) continue;
    const o = overlap(counted(results[i].listings, results[i].stats), counted(results[j].listings, results[j].stats));
    pairs.push({ i, j, ...o });
    if (o.min_sales_on_shared_pct >= 70) parent[find(i)] = find(j);
  }
  const groups = {};
  results.forEach((res, i) => { (groups[find(i)] ??= []).push(i); });
  return Object.values(groups).map(idx => {
    const members = idx.map(i => results[i]);
    const name = members.map(m => m.keyword).sort((a, b) => a.length - b.length)[0];
    let combined = null;
    if (members.length > 1) {
      // One market, measured once: every counted listing from every variant, de-duplicated by ASIN
      const seen = new Set();
      const union = [];
      for (const m of members) for (const l of counted(m.listings, m.stats)) {
        if (seen.has(l.asin)) continue;
        seen.add(l.asin);
        union.push({ ...l, keyword: name, relevant: true });
      }
      combined = marketStats(union);
    }
    const variants = members.map(m => {
      const mine = counted(m.listings, m.stats);
      const others = new Set(members.filter(o => o !== m).flatMap(o => counted(o.listings, o.stats).map(l => l.asin)));
      const unique = mine.filter(l => !others.has(l.asin));
      const totalUnits = mine.reduce((s, l) => s + (l.bought_last_month ?? 0), 0);
      const uniqueUnits = unique.reduce((s, l) => s + (l.bought_last_month ?? 0), 0);
      return {
        keyword: m.keyword,
        unique_products: members.length > 1 ? unique.length : null,
        unique_sales_share_pct: members.length > 1 && totalUnits ? r(uniqueUnits / totalUnits * 100, 1) : null,
        unique_price_median: members.length > 1 ? r(quantile(unique.map(l => l.price), 0.5)) : null,
        unique_top_titles: members.length > 1
          ? [...unique].sort((a, b) => (b.bought_last_month ?? 0) - (a.bought_last_month ?? 0)).slice(0, 3)
            .map(l => `${l.title.slice(0, 60)} (${l.bought_last_month ?? 'no'} sold)`) : [],
      };
    });
    const memberPairs = pairs.filter(p => idx.includes(p.i) && idx.includes(p.j))
      .map(p => `${results[p.i].keyword} / ${results[p.j].keyword}: ${p.min_sales_on_shared_pct}% shared sales`);
    // Relations to keywords outside this market, checked from BOTH sides.
    // Sub-segment: 50%+ of this keyword's sales sit on products that also rank for the other keyword, but those
    // products are under 50% of the other keyword's sales. Live example (Oct 16): "resistance bands with handles"
    // 64.6% on shared products, which are 13.7% of "resistance bands" sales.
    const relations = [];
    let parentOf = null;
    for (const p of pairs) {
      const inI = idx.includes(p.i), inJ = idx.includes(p.j);
      if (inI === inJ) continue;
      const [me, other, mine, theirs] = inI
        ? [results[p.i].keyword, results[p.j].keyword, p.a_sales_on_shared_pct, p.b_sales_on_shared_pct]
        : [results[p.j].keyword, results[p.i].keyword, p.b_sales_on_shared_pct, p.a_sales_on_shared_pct];
      if (mine >= 50 && theirs < 50) {
        relations.push(`sub-segment of "${other}": ${mine}% of "${me}" sales are on products that also rank for "${other}"; those products are ${theirs}% of "${other}" sales`);
        if (!parentOf || mine > parentOf.mine) parentOf = { other, mine };
      } else if (theirs >= 50 && mine < 50) {
        relations.push(`contains sub-segment "${other}": ${theirs}% of "${other}" sales are on products that also rank for "${me}"; those products are ${mine}% of "${me}" sales`);
      } else if (Math.min(mine, theirs) >= 30) {
        relations.push(`overlaps "${other}": ${mine}% / ${theirs}% of sales on shared products (not merged)`);
      }
    }
    return { market: name, marketplace: members[0].marketplace, idx, keywords: members.map(m => m.keyword), combined, variants, member_pairs: memberPairs, relations, sub_segment_of: parentOf?.other ?? null };
  });
}


// ===================== Toolkit Core: entry point =====================
// Input: ONE item from the calling tool (i1, i2, i3 or i4):
//   { tool, batch_id, searches: [{ order, keyword, marketplace, response }], history: [Listings rows], dropped: [] }
// Output: ONE item: { keywords: [...rows], listings: [...rows], markets: [...rows], summary_text }
const input = $input.first().json;
const CURRENCY = { 'amazon.com': '$', 'amazon.co.uk': '£', 'amazon.ca': 'C$' };
const CANNOT_TELL = [
  'how many shoppers search each keyword (no search volume in this data)',
  'profit, fees or margins (no costs or product sizes)',
  'whether demand is rising or falling (needs repeat runs over weeks)',
  'how long products have been on sale (no launch dates)',
].join(' | ');
// Score movement seen between consecutive runs of the same keyword (v2.1 score, Oct 9-16):
// stable 0-2 points, moderate up to 8. Unstable has only one sample, so it keeps a wide 12.
const NOISE = { stable: 3, moderate: 8, unstable: 12 };

// ---------- Clean one SerpApi response into listings ----------
const SLUG_STOP = new Set(['all', 'non', 'multi', 'heavy', 'natural', 'plant', 'pack', 'set', 'kitchen', 'home', 'new', 'premium',
  'upgraded', 'the', 'for', 'with', 'extra', 'super', 'large', 'small', 'eco', 'reusable', 'individually', 'biodegradable',
  'unisex', 'booty', 'fabric', 'panel', 'stainless', 'steel', 'wood', 'carbon', 'women', 'womens', 'men', 'mens', 'kids', 'thick', 'non', 'anti', 'professional', 'original']);
function cleanListings(res, keyword, marketplace) {
  const organic = res.organic_results || [];
  const checkedAt = res.search_metadata?.processed_at ?? new Date().toISOString();
  const runId = `${keyword}|${marketplace}|${checkedAt}`;
  const kwStems = kwStemsOf(keyword);
  const parseBought = text => {
    if (!text) return null;
    const m = String(text).match(/([\d.]+)\s*(K)?\+/i);
    return m ? Math.round(parseFloat(m[1]) * (m[2] ? 1000 : 1)) : null;
  };
  // Brand: first title word; if that is generic, the first word of the product URL
  // (Amazon puts a short name in the URL, and sellers with generic titles often have their brand there: /VanStretch-Resistance-.../dp/)
  function brandOf(p) {
    const first = (p.title || '').split(' ')[0].replace(/[®™,]/g, '');
    if (!/^\d/.test(first) && cleanBrand(first, kwStems)) return { brand: first, source: 'title' };
    const m = (p.link || '').match(/amazon\.[a-z.]+\/([^/?]+)\/dp\//i);
    const tok = m ? decodeURIComponent(m[1]).split('-')[0] : '';
    const w = tok.toLowerCase().replace(/[^a-z0-9]/g, '');
    const inTitle = (p.title || '').toLowerCase().includes(w);
    if (tok && w.length >= 3 && !/^\d/.test(w) && !SLUG_STOP.has(w) && !inTitle && cleanBrand(tok, kwStems)) return { brand: tok, source: 'url' };
    return { brand: /^\d/.test(first) ? null : first, source: 'title' };
  }
  const kwWords = kwStems;
  const head = kwWords[kwWords.length - 1];
  const ACCESSORY = /\b(towels?|blocks?|wheels?|socks?)\b/i;
  const seen = new Set();
  const out = [];
  for (const p of organic) {
    if (p.sponsored === true) continue;
    if (typeof p.extracted_price !== 'number' || p.extracted_price <= 0 || !p.title) continue;
    const key = `${p.title.toLowerCase()}|${p.reviews ?? 0}`;
    if (seen.has(key)) continue;
    seen.add(key);
    const text = `${p.title} ${(p.link_clean || '').replace(/[-_/]/g, ' ')}`.toLowerCase();
    const exact = kwWords.every(w => text.includes(w));
    const broad = head ? text.includes(head) : true;
    const oldPrice = p.extracted_old_price ?? null;
    const b = brandOf(p);
    out.push({
      run_id: runId, keyword, marketplace, checked_at: checkedAt,
      position: p.position, asin: p.asin, title: p.title,
      relevant: broad && !ACCESSORY.test(p.title),
      match_type: exact ? 'exact' : broad ? 'broad' : 'none',
      brand_guess: b.brand, brand_source: b.source,
      price: p.extracted_price, old_price: oldPrice,
      discount_pct: oldPrice ? Math.round((1 - p.extracted_price / oldPrice) * 100) : 0,
      rating: p.rating ?? null, reviews: p.reviews ?? 0,
      bought_last_month: parseBought(p.bought_last_month),
      badges: (p.badges || []).join(', '),
      small_business: p.small_business === true,
      url: p.link_clean,
    });
  }
  if (out.length === 0) throw new Error(`No usable listings for "${keyword}". Check the spelling or try a broader keyword.`);
  const page = {
    sponsored_on_page: organic.filter(p => p.sponsored === true).length,
    organic_on_page: organic.filter(p => p.sponsored !== true).length,
    total_results: res.search_information?.total_results ?? null,
    related_searches: (res.related_searches || []).map(x => x.query).filter(Boolean).join(' | '),
    shopping_ideas: (res.filters?.popular_shopping_ideas || []).map(x => x.name).filter(Boolean).join(' | '),
  };
  return { listings: out, page, run_id: runId, checked_at: checkedAt };
}

// ---------- History rows (from the Listings tab) back into listing objects ----------
// Sheets may hand numbers back as text ("1,000", "$17.99"), so strip formatting before converting
const toNum = v => {
  if (v === '' || v === null || v === undefined) return null;
  const x = typeof v === 'number' ? v : Number(String(v).replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(x) ? x : null;
};
const toBool = v => v === true || String(v).toUpperCase() === 'TRUE';
function fromRow(row) {
  return {
    run_id: row.run_id, keyword: row.keyword, marketplace: row.marketplace, checked_at: row.checked_at,
    position: toNum(row.position), asin: row.asin, title: String(row.title ?? ''),
    relevant: row.relevant === '' || row.relevant === undefined ? true : toBool(row.relevant),
    match_type: row.match_type || 'exact', brand_guess: row.brand_guess || null,
    price: toNum(row.price), old_price: toNum(row.old_price), discount_pct: toNum(row.discount_pct) ?? 0,
    rating: toNum(row.rating), reviews: toNum(row.reviews) ?? 0, bought_last_month: toNum(row.bought_last_month),
    badges: row.badges || '', small_business: toBool(row.small_business),
  };
}
const historyRuns = {};
for (const row of input.history || []) {
  if (!row.run_id || !row.asin) continue;
  (historyRuns[row.run_id] ??= []).push(fromRow(row));
}
function previousRun(keyword, marketplace, runId, checkedAt) {
  const candidates = Object.entries(historyRuns)
    .filter(([id, ls]) => id !== runId && ls[0].keyword === keyword && ls[0].marketplace === marketplace && String(ls[0].checked_at) < String(checkedAt))
    .sort((a, b) => String(b[1][0].checked_at).localeCompare(String(a[1][0].checked_at)));
  return candidates[0]?.[1] ?? null;
}

function errorText(res) {
  const e = res?.error;
  if (!e) return null;
  let msg = typeof e === 'string' ? e : (e.message || e.description || JSON.stringify(e));
  const m = String(msg).match(/\\?"error\\?"\s*:\s*\\?"(.+?)\\?"/);
  if (m) msg = m[1];
  return String(msg).replace(/\s+/g, ' ').trim().slice(0, 200);
}
const confLabel = p => (p >= 2 ? 'high' : p === 1 ? 'medium' : 'low');
const worse = (a, b) => {
  const order = ['unstable', 'moderate', 'no previous run', 'cached copy', 'stable'];
  return order.indexOf(a) <= order.indexOf(b) ? a : b;
};

// ---------- Run every keyword ----------
const results = [];
const keywordRows = [];
const listingRows = [];
for (const s of input.searches || []) {
  const base = {
    tool: input.tool, batch_id: input.batch_id, order: s.order, keyword: s.keyword, marketplace: s.marketplace,
    currency: CURRENCY[s.marketplace] ?? '', core_version: CORE_VERSION,
  };
  try {
    // A tool can hand over an already-saved run instead of a fresh search (the deep dive reuses a recent screener run).
    const reused = Array.isArray(s.listings) && s.listings.length > 0;
    let c;
    if (reused) {
      const ls = s.listings.map(fromRow);
      c = { listings: ls, page: {}, run_id: ls[0].run_id, checked_at: ls[0].checked_at };
    } else {
      const err = errorText(s.response);
      if (err && !(s.response?.organic_results || []).length) throw new Error(`SerpApi: ${err}`);
      c = cleanListings(s.response, s.keyword, s.marketplace);
    }
    const stats = marketStats(c.listings);
    let conf = stats.confidence_points;
    const notes = [...stats.confidence_notes];

    // Stability vs the previous run of this keyword in this marketplace
    let stab;
    if (!reused && historyRuns[c.run_id]) {
      stab = { stability: 'cached copy', note: `same search result as the run already saved at ${c.checked_at} (SerpApi caches identical searches for 1 hour), so not a new measurement` };
    } else {
      const prev = previousRun(s.keyword, s.marketplace, c.run_id, c.checked_at);
      let prevStats = null;
      try { prevStats = prev ? marketStats(prev) : null; } catch (e) { prevStats = null; }
      stab = prevStats ? stability(c.listings, stats, prev, prevStats) : { stability: 'no previous run', note: 'first run of this keyword here, stability not measured' };
    }
    if (stab.stability === 'unstable') { conf--; notes.push(`page 1 changed a lot since the last run (${stab.note})`); }

    if (reused) notes.push(`reused the saved run from ${c.checked_at} instead of a new search`);
    results.push({ keyword: s.keyword, marketplace: s.marketplace, listings: c.listings, stats, stab, page: c.page, run_id: c.run_id, conf, notes, base, reused });
    if (!reused) for (const l of c.listings) {
      const why = stats.excluded[`${l.asin}|${l.position}`] || '';
      listingRows.push({
        row_id: `${c.run_id}|${l.asin}|${l.position}`, run_id: c.run_id, tool: input.tool, batch_id: input.batch_id,
        keyword: l.keyword, marketplace: l.marketplace, checked_at: l.checked_at, position: l.position, asin: l.asin,
        family_id: stats.family_of[`${l.asin}|${l.position}`] || '', title: l.title,
        brand_guess: l.brand_guess, brand_source: l.brand_source, in_stats: !why, excluded_reason: why,
        relevant: l.relevant, match_type: l.match_type, price: l.price, old_price: l.old_price, discount_pct: l.discount_pct,
        rating: l.rating, reviews: l.reviews, bought_last_month: l.bought_last_month, badges: l.badges,
        small_business: l.small_business, url: l.url,
      });
    }
  } catch (e) {
    keywordRows.push({ ...base, row_id: `${input.batch_id}|${s.keyword}|${s.marketplace}`, status: 'failed', note: String(e.message || e).slice(0, 300) });
  }
}

// ---------- Group variants into markets ----------
const groups = groupVariants(results);
const marketRows = [];
for (const g of groups) {
  const members = g.idx.map(i => results[i]);
  const s = g.combined || members[0].stats;
  const stab = members.map(m => m.stab.stability).reduce(worse);
  let conf = g.combined ? g.combined.confidence_points : members[0].conf;
  const notes = g.combined ? [...g.combined.confidence_notes] : [...members[0].notes];
  if (g.combined && stab === 'unstable') { conf--; notes.push('at least one keyword in this market changed a lot since its last run'); }
  const variantNote = g.keywords.length > 1
    ? [...g.member_pairs, ...g.variants.map(v => `"${v.keyword}" alone shows ${v.unique_products} products (${v.unique_sales_share_pct}% of its sales, median ${CURRENCY[members[0].marketplace] ?? ''}${v.unique_price_median})`)].join(' | ')
    : '';
  marketRows.push({
    market: g.market, marketplace: members[0].marketplace, keywords: g.keywords.join(', '),
    _thin: members.some(x => x.stats.thin_page),
    opportunity_score: s.opportunity_score, confidence: confLabel(conf), stability: stab,
    products_analyzed: s.products_analyzed, price_p25: s.price_p25, price_median: s.price_median, price_p75: s.price_p75,
    median_reviews: s.median_reviews, units_last_month_floor: s.units_last_month_floor, revenue_last_month_floor: s.revenue_last_month_floor,
    top_brand: s.top_brand, top_brand_sales_share_pct: s.top_brand_sales_share_pct, unknown_brand_sales_share_pct: s.unknown_brand_sales_share_pct,
    top3_products_sales_share_pct: s.top3_products_sales_share_pct,
    low_review_sellers_count: s.low_review_sellers_count, low_review_sales_share_pct: s.low_review_sales_share_pct,
    low_review_price_median: s.low_review_price_median, amazon_own_brand_products: s.amazon_own_brand_products,
    variant_note: variantNote, related_markets: g.relations.join(' | '), sub_segment_of: g.sub_segment_of ?? '',
    score_breakdown: s.score_breakdown.join(' | '), confidence_notes: notes.join(' | '),
    cannot_tell: CANNOT_TELL, checked_at: members[0].stats.checked_at,
  });
  for (const m of members) {
    const v = g.variants.find(x => x.keyword === m.keyword);
    const st = m.stats;
    keywordRows.push({
      ...m.base, row_id: `${input.batch_id}|${m.keyword}|${m.marketplace}`, run_id: m.run_id, status: 'ok',
      market: g.market, market_keywords: g.keywords.join(', '), checked_at: st.checked_at,
      opportunity_score: st.opportunity_score, confidence: confLabel(m.conf), stability: m.stab.stability,
      score_change_vs_prev: m.stab.score_change ?? '', sales_on_shared_with_prev_pct: m.stab.sales_on_shared_with_prev_pct ?? '',
      listings_analyzed: st.listings_analyzed, products_analyzed: st.products_analyzed, variation_groups: st.variation_groups,
      exact_match_pct: st.exact_match_pct, price_p25: st.price_p25, price_median: st.price_median, price_p75: st.price_p75,
      avg_rating: st.avg_rating, median_reviews: st.median_reviews, top3_review_share_pct: st.top3_review_share_pct,
      units_last_month_floor: st.units_last_month_floor, revenue_last_month_floor: st.revenue_last_month_floor,
      listings_missing_sales: st.listings_missing_sales, top3_products_sales_share_pct: st.top3_products_sales_share_pct,
      top_brand: st.top_brand, top_brand_sales_share_pct: st.top_brand_sales_share_pct, unknown_brand_sales_share_pct: st.unknown_brand_sales_share_pct,
      amazon_own_brand_products: st.amazon_own_brand_products, low_review_sellers_count: st.low_review_sellers_count,
      low_review_sales_share_pct: st.low_review_sales_share_pct, low_review_price_median: st.low_review_price_median,
      low_review_avg_rating: st.low_review_avg_rating, deal_event_share_pct: st.deal_event_share_pct,
      discounted_outside_event_pct: st.discounted_outside_event_pct, bulk_listings: st.bulk_listings, outliers_removed: st.outliers_removed,
      ...m.page,
      unique_products_vs_variants: v?.unique_products ?? '', unique_sales_share_pct: v?.unique_sales_share_pct ?? '',
      unique_price_median: v?.unique_price_median ?? '', unique_top_titles: (v?.unique_top_titles || []).join(' | '),
      score_breakdown: st.score_breakdown.join(' | '), confidence_notes: m.notes.join(' | '), stability_note: m.stab.note,
    });
  }
}

// Rank markets. A gap smaller than the run-to-run movement seen for that stability level is not a real difference.
marketRows.sort((a, b) => b.opportunity_score - a.opportunity_score);
marketRows.forEach((m, i) => {
  m.rank = i + 1;
  m.row_id = `${input.batch_id}|${m.market}|${m.marketplace}`;
  m.batch_id = input.batch_id;
  m.tool = input.tool;
  const next = marketRows[i + 1];
  if (next) {
    // A thin page (under 30 listings) swings more: phone stand moved 7 points between two 'stable' runs of 16 listings
    const noiseOf = x => (x._thin ? 12 : NOISE[x.stability] ?? 12);
    const noise = Math.max(noiseOf(m), noiseOf(next));
    const gap = m.opportunity_score - next.opportunity_score;
    m.vs_next = gap >= noise
      ? `ahead of "${next.market}"${next.marketplace !== m.marketplace ? ` (${next.marketplace})` : ''} by ${gap} (more than the ${noise}-point run-to-run movement)`
      : `ahead of "${next.market}"${next.marketplace !== m.marketplace ? ` (${next.marketplace})` : ''} by only ${gap}; scores move up to ${noise} points between runs, so treat these two as tied`;
  } else m.vs_next = '';
});

for (const k of input.dropped || []) {
  keywordRows.push({ tool: input.tool, batch_id: input.batch_id, row_id: `${input.batch_id}|${k}|${input.searches?.[0]?.marketplace ?? ''}`,
    keyword: k, status: 'skipped', note: 'Over the 10-keyword limit per run. Run it in the next batch.' });
}

const tried = keywordRows.filter(x => x.status !== 'skipped');
if (tried.length > 0 && tried.every(x => x.status === 'failed')) {
  const reason = `${tried[0].keyword} - ${tried[0].note}`.replace(/:\s/g, ' - ');
  throw new Error(`All ${tried.length} keywords failed. First one was ${reason}`);
}

keywordRows.sort((a, b) => (a.order || 99) - (b.order || 99));
for (const mr of marketRows) delete mr._thin;
const summary_text = marketRows.map(m => `#${m.rank} ${m.market} (${m.marketplace}): ${m.opportunity_score}/100, confidence ${m.confidence}${m.keywords.includes(',') ? ` [${m.keywords}]` : ''}${m.sub_segment_of ? ` (sub-segment of ${m.sub_segment_of})` : ''}`).join('\n')
  + (keywordRows.some(k => k.status !== 'ok') ? `\nNot analyzed: ${keywordRows.filter(k => k.status !== 'ok').map(k => `${k.keyword} (${k.status})`).join(', ')}` : '');

// Extra detail for tools that need it (the deep dive picks products from the families). Not written to any sheet.
const details = results.map(x => ({
  keyword: x.keyword, marketplace: x.marketplace, run_id: x.run_id, checked_at: x.stats.checked_at, reused: !!x.reused,
  confidence: confLabel(x.conf), confidence_notes: x.notes.join(' | '), stability: x.stab.stability, stability_note: x.stab.note,
  stats: Object.fromEntries(Object.entries(x.stats).filter(([k]) => !['excluded', 'family_of', 'families', 'outliers', 'low_review_sellers'].includes(k))),
  families: x.stats.families,
}));
return [{ json: { keywords: keywordRows, listings: listingRows, markets: marketRows, summary_text, details } }];
